create function public.billing_admin_authorized_session() returns boolean
language plpgsql stable security definer set search_path='' as $$
declare sid text:=auth.jwt()->>'session_id';begin
 if current_setting('role',true)<>'authenticated' or sid is null or sid !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then return false;end if;
 return exists(select 1 from auth.users u join auth.sessions s on s.user_id=u.id join private.app_session_activity a on a.session_id=s.id and a.user_id=u.id
 join public.platform_admins p on p.user_id=u.id and p.role='owner' and p.status='active'
 where u.id=auth.uid() and s.id=sid::uuid and (u.email_confirmed_at is not null or u.phone_confirmed_at is not null)
 and a.expired_at is null and a.last_activity_at<=statement_timestamp() and a.last_activity_at>statement_timestamp()-interval '2 hours');
end;$$;
revoke all on function public.billing_admin_authorized_session() from public,anon,authenticated,service_role;
grant execute on function public.billing_admin_authorized_session() to authenticated;
create function public.billing_admin_read_order_page(p_input jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare cid uuid;env text;lo timestamptz;hi timestamptz;snap timestamptz;cur timestamptz;curid uuid;n integer;rows jsonb;total bigint;
begin
 if not public.billing_admin_authorized_session() then return jsonb_build_object('ok',false,'code','forbidden');end if;
 if jsonb_typeof(p_input) is distinct from 'object' then return jsonb_build_object('ok',false,'code','invalid_input');end if;
 cid:=nullif(p_input->>'company_id','')::uuid;env:=coalesce(p_input->>'environment','all');lo:=nullif(p_input->>'from','')::timestamptz;hi:=nullif(p_input->>'until','')::timestamptz;
 snap:=coalesce(nullif(p_input->>'snapshot','')::timestamptz,statement_timestamp());cur:=nullif(p_input->>'cursor_created_at','')::timestamptz;curid:=nullif(p_input->>'cursor_id','')::uuid;n:=coalesce((p_input->>'page_size')::integer,25);
 if env not in('all','live','test','unknown') or n<1 or n>100 or snap>statement_timestamp() or (cur is null)<>(curid is null) or cur>snap or lo>=hi then return jsonb_build_object('ok',false,'code','invalid_input');end if;
 select count(*) into total from public.billing_orders o where (cid is null or o.company_id=cid) and o.created_at<=snap and (lo is null or o.created_at>=lo) and (hi is null or o.created_at<hi)
 and (env='all' or o.provider_environment=env or env='unknown' and (o.provider_environment is null or o.provider_environment not in('live','test')));
 select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc,x.id desc),'[]'::jsonb) into rows from (
 select o.id,o.company_id,c.display_name company_name,o.plan_version_id,o.amount_baisa,o.currency,o.period_days,o.period_unit,o.period_count,o.provider,o.provider_account_ref,o.provider_environment,o.provider_amount,o.provider_amount_unit,o.status,o.purchase_purpose,o.created_at,o.expires_at,o.deadline_policy_approved
 from public.billing_orders o join public.companies c on c.id=o.company_id
 where (cid is null or o.company_id=cid) and o.created_at<=snap and (lo is null or o.created_at>=lo) and (hi is null or o.created_at<hi)
 and (env='all' or o.provider_environment=env or env='unknown' and (o.provider_environment is null or o.provider_environment not in('live','test')))
 and (cur is null or (o.created_at,o.id)<(cur,curid)) order by o.created_at desc,o.id desc limit n+1
 ) x;
 return jsonb_build_object('ok',true,'orders',rows,'total',total,'snapshot',snap);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then return jsonb_build_object('ok',false,'code','invalid_input');
end;$$;
revoke all on function public.billing_admin_read_order_page(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.billing_admin_read_order_page(jsonb) to authenticated;
create function public.billing_admin_read_service_state(p_company_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare states jsonb;begin
 if not public.billing_admin_authorized_session() then return jsonb_build_object('ok',false,'code','forbidden');end if;
 select coalesce(jsonb_agg(jsonb_build_object('service',so.service_code,'tier',so.tier,'activated',sg.activated) order by so.service_code,so.tier),'[]'::jsonb) into states
 from private.billing_service_grants sg join private.billing_service_order_offers so on so.order_id=sg.order_id
 join private.billing_proven_entitlement_grants g on g.id=sg.entitlement_application_id and g.order_id=sg.order_id and g.plan_version_id=so.plan_version_id
 join public.billing_subscriptions s on s.id=g.subscription_id and s.company_id=g.company_id and s.plan_version_id=g.plan_version_id and s.paid_through=g.applied_paid_through
 join public.companies c on c.id=g.company_id and c.status='active'
 where g.company_id=p_company_id and g.provider_environment='live' and so.environment='live' and s.environment='live'
 and s.status in('active','cancel_at_period_end') and s.paid_through>statement_timestamp() and private.billing_service_receipt_eligible(g.id);
 return jsonb_build_object('ok',true,'company_id',p_company_id,'states',states);
end;$$;
revoke all on function public.billing_admin_read_service_state(uuid) from public,anon,authenticated,service_role;
grant execute on function public.billing_admin_read_service_state(uuid) to authenticated;
